import{c as a,Q as e,j as l,m as s}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"AllocMutexID (ISASI)","description":"","frontmatter":{},"headers":[{"level":1,"title":"AllocMutexID \\\\(ISASI\\\\)","slug":"allocmutexid-isasi"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/同步控制/核内同步/AllocMutexID-(ISASI).md","filePath":"api/SIMD-API/基础API/同步控制/核内同步/AllocMutexID-(ISASI).md"}'),n={name:"api/SIMD-API/基础API/同步控制/核内同步/AllocMutexID-(ISASI).md"};function i(d,t,o,c,p,r){return e(),l("div",null,[...t[0]||(t[0]=[s(`<h1 id="allocmutexid-isasi" tabindex="-1">AllocMutexID (ISASI) <a class="header-anchor" href="#allocmutexid-isasi" aria-label="Permalink to &quot;AllocMutexID \\(ISASI\\)&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>从框架获取并占用一个MutexID，与<a href="./ReleaseMutexID-(ISASI).html">ReleaseMutexID</a>配合使用，管理MutexID的获取和释放。获取的MutexID可以传入<a href="./Mutex（ISASI）/Mutex（ISASI）.html">Mutex::Lock/Unlock</a>接口使用，此时Mutex::Lock/Unlock可以与TQue等其他接口配合使用。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline MutexID AllocMutexID()</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p>无</p><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>返回MutexID，其类型定义如下，每个ID表示一个Mutex锁。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>using MutexID = uint8_t;</span></span></code></pre></div><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>MutexID有数量限制，使用结束应该立刻调用ReleaseMutexID释放，防止MutexID耗尽。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MutexID id = AllocMutexID();</span></span>
<span class="line"><span>Mutex::Lock&lt;PIPE_MTE2&gt;(id);</span></span>
<span class="line"><span>DataCopy(local, gm, 1024);</span></span>
<span class="line"><span>Mutex::Unlock&lt;&lt;PIPE_MTE2&gt;(id);</span></span>
<span class="line"><span>Mutex::Lock&lt;PIPE_V&gt;(id);</span></span>
<span class="line"><span>Adds(local, local, 1, 1024);</span></span>
<span class="line"><span>Mutex::Unlock&lt;PIPE_V&gt;(id);</span></span>
<span class="line"><span>ReleaseMutexID(id);</span></span></code></pre></div>`,16)])])}const I=a(n,[["render",i]]);export{h as __pageData,I as default};
